/* 부재관리 (7070) */
/* AdminAbsenceMapper.selectListTotCnt */
SELECT COUNT(*) totcnt
FROM CSPD101TI
WHERE 1=1
AND AI_INPT_AUT_CD IN ('01','03')

mapper.sql:
AND AI_INPT_USER_YN = 'Y'

	AND AI_INPT_AUT_CD = #{schAuth}


	AND AI_INPT_USER_ENO LIKE '%' || #{schUserNo} || '%'


	AND AI_INPT_USER_NM LIKE '%' || #{schUserNm} || '%'


	AND AI_INPT_USER_FA_RE_YN = #{aiInptUserFaReYn}

mapper.update:
/* 부재관리 (7070) */
/* AdminAbsenceMapper.existUpdate */
/* 부재여부 업데이트 처리 */
UPDATE CSPD101TI SET
	AI_INPT_USER_FA_RE_YN = NVL(#{aiInptUserFaReYn},'N')	/* 부재여부 - 부재중(Y), 부재아님(N) */
	, LST_DB_CHG_ID = #{lstDbChgId}
	, LST_DB_CHG_DTM = TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS')
	, TRN_LOG_SRNO = #{trnLogSrno}
WHERE AI_INPT_USER_ENO = #{aiInptUserEno}
